import app from 'flarum/forum/app';
import FormModal from 'flarum/common/components/FormModal';
import Button from 'flarum/common/components/Button';
import extractText from 'flarum/common/utils/extractText';
import { about, arrivalDate, call, countryName, errorText, t } from '../api';
import { STAMPS, Stamp } from '../art';
import { avatar } from './Envelopes';
const MAX = 6000;
const STAMP_KEY = 'slowMail.stamp';

/**
 * The writing desk: who to, a stamp, the letter, and how long it will take
 * to get there (asked of the server as soon as there is a recipient: the
 * same answer sending gives). Sending folds the letter away.
 */
export default class WriteModal extends FormModal {
  to = null;
  query = '';
  results = [];
  searching = false;
  searchTimer = 0;
  stamp = 'lighthouse';
  body = '';
  quote = null;
  quoting = false;
  sent = false;
  oninit(vnode) {
    super.oninit(vnode);
    this.to = this.attrs.to || null;
    try {
      const saved = localStorage.getItem(STAMP_KEY);
      if (saved && STAMPS.includes(saved)) this.stamp = saved;
    } catch {
      // Private windows can refuse storage: the default stamp is fine.
    }
    if (this.stamp === 'home' && !this.attrs.home?.country) this.stamp = 'lighthouse';
    if (this.to) this.fetchQuote();
  }
  className() {
    return 'SlowMailWrite Modal--medium' + (this.sent ? ' is-sent' : '');
  }
  title() {
    return this.attrs.replyTo ? t('write.reply_title', {
      name: this.to?.displayName
    }) : t('write.title');
  }
  content() {
    if (this.sent) return this.sentView();
    return m("div", {
      className: "Modal-body"
    }, this.recipientField(), this.stampField(), m("div", {
      className: "Form-group"
    }, m("label", {
      for: "SlowMailWrite-body"
    }, t('write.letter')), m("textarea", {
      id: "SlowMailWrite-body",
      className: "FormControl SlowMailWrite-paper",
      rows: 10,
      maxlength: MAX,
      placeholder: extractText(t('write.placeholder', {
        name: this.to?.displayName || ''
      })),
      value: this.body,
      oninput: e => this.body = e.target.value
    }), m("p", {
      className: "helpText SlowMailWrite-count"
    }, t('write.count', {
      count: this.body.length,
      max: MAX
    }))), this.journeyNote(), m("div", {
      className: "Form-group"
    }, m(Button, {
      type: "submit",
      className: "Button Button--primary Button--block",
      icon: "fas fa-paper-plane",
      loading: this.loading,
      disabled: !this.to || !this.body.trim() || this.quote !== null && !this.quote.ok
    }, t('write.send'))));
  }
  recipientField() {
    if (this.to) {
      return m("div", {
        className: "Form-group SlowMailWrite-to"
      }, m("label", null, t('envelope.to')), m("div", {
        className: "SlowMailWrite-person"
      }, avatar(this.to), m("span", {
        className: "SlowMailWrite-personName"
      }, this.to.displayName), this.attrs.to ? null : m(Button, {
        className: "Button Button--link",
        onclick: () => this.pick(null)
      }, t('write.change'))));
    }
    return m("div", {
      className: "Form-group SlowMailWrite-to"
    }, m("label", {
      for: "SlowMailWrite-search"
    }, t('envelope.to')), m("input", {
      id: "SlowMailWrite-search",
      className: "FormControl",
      autocomplete: "off",
      placeholder: extractText(t('write.search')),
      value: this.query,
      oninput: e => this.search(e.target.value)
    }), this.results.length ? m("ul", {
      className: "SlowMailWrite-results",
      role: "listbox"
    }, this.results.map(person => m("li", null, m("button", {
      type: "button",
      className: "SlowMailWrite-result",
      onclick: () => this.pick(person)
    }, avatar(person), " ", m("span", null, person.displayName))))) : this.query.length > 1 && !this.searching ? m("p", {
      className: "helpText"
    }, t('write.no_results')) : null);
  }
  stampField() {
    const country = this.attrs.home?.country;
    return m("div", {
      className: "Form-group"
    }, m("label", null, t('write.stamp')), m("div", {
      className: "SlowMailWrite-stamps",
      role: "radiogroup"
    }, STAMPS.filter(name => name !== 'home' || country).map(name => m("button", {
      type: "button",
      role: "radio",
      "aria-checked": this.stamp === name ? 'true' : 'false',
      className: 'SlowMailWrite-stamp' + (this.stamp === name ? ' is-chosen' : ''),
      title: extractText(t(`stamps.${name}`)),
      onclick: () => this.choose(name)
    }, Stamp({
      name,
      country,
      title: extractText(t(`stamps.${name}`))
    })))));
  }
  journeyNote() {
    if (!this.to) return null;
    if (this.quoting && !this.quote) return m("p", {
      className: "SlowMailWrite-journey"
    }, t('write.measuring'));
    const q = this.quote;
    if (!q) return null;
    if (!q.ok) return m("p", {
      className: "SlowMailWrite-journey is-refused"
    }, t('errors.slow_mail_not_accepting'));
    const from = q.postmark || countryName(q.origin);
    return m("p", {
      className: "SlowMailWrite-journey"
    }, t('write.takes', {
      name: this.to.displayName,
      time: about(q.hours || 0)
    }), ' ', m("span", {
      className: "SlowMailWrite-when"
    }, arrivalDate(q.arrivesAt)), from && q.destination ? m("span", {
      className: "SlowMailWrite-route"
    }, t('write.route', {
      from,
      to: q.destination
    })) : null, q.mapped ? null : m("span", {
      className: "SlowMailWrite-route"
    }, t('write.no_map')), q.limit ? m("span", {
      className: "SlowMailWrite-limit"
    }, errorText({
      response: {
        errors: [{
          code: q.limit
        }]
      }
    })) : null);
  }
  sentView() {
    return m("div", {
      className: "Modal-body SlowMailWrite-done"
    }, m("div", {
      className: "SlowMailWrite-fold",
      "aria-hidden": "true"
    }, m("span", {
      className: "SlowMailWrite-foldSheet"
    }), m("span", {
      className: "SlowMailWrite-foldEnvelope"
    }, Stamp({
      name: this.stamp,
      country: this.attrs.home?.country
    }))), m("p", {
      className: "SlowMailWrite-doneText"
    }, t('write.sent', {
      name: this.to?.displayName,
      time: about(this.quote?.hours || 0)
    })), m(Button, {
      className: "Button Button--primary",
      onclick: () => this.hide()
    }, t('write.done')));
  }
  choose(name) {
    this.stamp = name;
    try {
      localStorage.setItem(STAMP_KEY, name);
    } catch {
      // Not remembered: fine.
    }
  }
  pick(person) {
    this.to = person;
    this.quote = null;
    this.results = [];
    this.query = '';
    if (person) this.fetchQuote();
  }
  search(value) {
    this.query = value;
    clearTimeout(this.searchTimer);
    if (value.trim().length < 2) {
      this.results = [];
      return;
    }
    this.searching = true;
    this.searchTimer = window.setTimeout(() => {
      app.store.find('users', {
        filter: {
          q: value.trim()
        },
        page: {
          limit: 6
        }
      }).then(users => {
        if (this.query !== value) return;
        const me = app.session.user?.id();
        this.results = users.filter(u => u.id() !== me).map(u => ({
          id: Number(u.id()),
          slug: u.slug(),
          displayName: u.displayName(),
          avatarUrl: u.avatarUrl()
        }));
      }).catch(() => this.results = []).finally(() => {
        this.searching = false;
        m.redraw();
      });
    }, 250);
  }
  fetchQuote() {
    if (!this.to) return;
    const id = this.to.id;
    this.quoting = true;
    call('GET', '/quote?to=' + id, undefined, true).then(q => {
      if (this.to?.id === id) this.quote = q;
    }).catch(() => this.quote = null).finally(() => {
      this.quoting = false;
      m.redraw();
    });
  }
  onsubmit(e) {
    e.preventDefault();
    if (!this.to || !this.body.trim()) return;
    this.loading = true;
    call('POST', '/letters', {
      to: this.to.id,
      body: this.body,
      stamp: this.stamp,
      replyTo: this.attrs.replyTo || null
    }).then(r => {
      this.loading = false;
      this.sent = true;
      this.attrs.onsent?.(r.letter);
      m.redraw();
    }, () => {
      this.loading = false;
      m.redraw();
    });
  }
}
flarum.reg.add('ernestdefoe-slow-mail', 'forum/components/WriteModal', WriteModal);